import {useEffect,useMemo,useState} from 'react';
import {api} from './api.js';
import {adminLogout,adminName,adminSignedIn,authHeaders,ADMIN_USERS} from './admin-auth.js';

const PLAN_STORAGE='giik.training-plans.v1', CARD_STORAGE='giik.card-workshop.v1';
const menu=[['home','⌂','Главная'],['users','♙','Пользователи'],['catalog','▦','Справочники'],['trainings','◇','Тренировки'],['scenarios','▱','Сценарии'],['cards','▤','Карточки'],['results','▥','Результаты'],['monitoring','▣','Мониторинг'],['system','⚙','Управление системой'],['settings','☼','Настройки']];
const statusLabel={queued:'Ожидает предыдущую',active:'Активна',submitted:'На проверке',pending_teacher:'На проверке',reviewed:'Завершена'};
const fmt=v=>{if(!v)return '—';try{return new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});}catch{return v;}};
const loadJSON=(key,fallback)=>{try{const v=JSON.parse(localStorage.getItem(key)||'null');return v??fallback;}catch{return fallback;}};
const saveUsers=list=>localStorage.setItem(ADMIN_USERS,JSON.stringify(list));
function useAdminData(){
 const [data,setData]=useState({sessions:[],tasks:[],scenarios:[],trainings:[],users:[],groups:[],error:'',loading:true});
 const refresh=async()=>{
  try{
   const [d,scenarios,trainings,users,groups]=await Promise.all([
    api('teacher_dashboard'),api('scenario_list'),api('training_list'),
    api('auth_users_list',{}, {headers:authHeaders()}),
    api('auth_groups_list',{}, {headers:authHeaders()})]);
   setData({...d,scenarios,trainings,users,groups,error:'',loading:false});
  }catch(e){
   if(e.status===401||e.code==='invalid_token'||e.code==='unauthorized'){adminLogout();location.replace('/admin-login');return;}
   setData(x=>({...x,error:e.message,loading:false}));
  }};
 useEffect(()=>{refresh();const t=setInterval(()=>{if(!document.hidden)refresh();},30000);return()=>clearInterval(t);},[]);
 return [data,refresh];
}
const ROLE_LABEL={admin:'Администратор',teacher:'Преподаватель',student:'Обучающийся'};
const ROLE_KEY={Администратор:'admin',Преподаватель:'teacher',Обучающийся:'student'};
const legacyUsers=list=>(Array.isArray(list)?list:[]).map(u=>({id:u.id,name:u.full_name||u.login,login:u.login,role:ROLE_LABEL[u.role]||u.role,status:u.is_active?'Активен':'Заблокирован',last_login:'',permissions:[]}));

function derived(data){
 const workshop=loadJSON(CARD_STORAGE,{cards:[]}),plans=data.scenarios||[];
 const users=legacyUsers(data.users);
 const groups=new Map();data.sessions.forEach(s=>{const id=s.training?.plan_id||s.training?.title||s.task_id||s.id;if(!groups.has(id))groups.set(id,{id,title:s.training?.title||s.title,teacher:s.training?.teacher||'—',group:s.training?.group||'—',mode:s.training?.mode==='testing'?'Тестирование':'Обучение',sessions:[],created_at:s.created_at});groups.get(id).sessions.push(s);});
 const trainings=[...data.trainings.map(t=>({...t,teacher:t.teacher,group:t.group,mode:t.mode==='testing'?'Тестирование':'Обучение',students:t.participants.length,created_at:t.created_at,sessions:data.sessions.filter(s=>s.training?.training_id===t.id),status:({prepared:'Подготовлена',active:'Активна',completed:'Завершена'})[t.status]})),...([...groups.values()].filter(g=>!data.trainings.some(t=>t.id===g.id)).map(t=>({...t,status:t.sessions.every(s=>s.status==='reviewed')?'Завершена':t.sessions.some(s=>s.status==='active')?'Активна':'Назначена',students:new Set(t.sessions.map(s=>s.student)).size})))];
 return {users,groups:Array.isArray(data.groups)?data.groups:[],cards:Array.isArray(workshop.cards)?workshop.cards:[],scenarios:Array.isArray(plans)?plans:[],trainings};
}
function Dot({tone='green'}){return <span className={'admin-dot '+tone}/>;}
function Drawer({title,onClose,children}){return <div className="admin-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><aside className="admin-drawer" role="dialog" aria-modal="true" aria-label={title}><header className="admin-drawer-head"><h2>{title}</h2><button onClick={onClose} aria-label="Закрыть">×</button></header>{children}</aside></div>;}
function Modal({title,onClose,children}){return <div className="admin-modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="admin-modal"><header><h3>{title}</h3><button onClick={onClose}>×</button></header>{children}</section></div>;}
function Tabs({items,value,onChange}){return <nav className="admin-tabs">{items.map(x=><button key={x[0]} className={value===x[0]?'active':''} onClick={()=>onChange(x[0])}>{x[1]}</button>)}</nav>;}
function Toolbar({search,setSearch,children}){return <div className="admin-toolbar"><label className="admin-search">⌕<input placeholder="Поиск" value={search} onChange={e=>setSearch(e.target.value)}/></label>{children}</div>;}
function Empty({text='Данных пока нет'}){return <div className="admin-empty">{text}</div>;}

function GroupPanel({groups,users,reload,err}){
 const [name,setName]=useState(''),[desc,setDesc]=useState(''),[selected,setSelected]=useState(''),[members,setMembers]=useState(null),[addUserId,setAddUserId]=useState('');
 const current=groups.find(g=>String(g.id)===String(selected))||groups[0];
 const loadMembers=async g=>{setSelected(String(g.id));try{setMembers(await api('auth_groups_members',{group_id:String(g.id)},{headers:authHeaders()}));}catch(e){err(e);}};
 const create=async()=>{if(!name.trim())return;try{await api('auth_groups_create',{name:name.trim(),description:desc.trim()},{headers:authHeaders()});setName('');setDesc('');reload();}catch(e){err(e);}};
 const removeGroup=async()=>{if(!current||!confirm('Удалить группу «'+current.name+'»?'))return;try{await api('auth_groups_delete',{group_id:String(current.id)},{headers:authHeaders()});setSelected('');setMembers(null);reload();}catch(e){err(e);}};
 const addMember=async()=>{if(!addUserId||!current)return;try{await api('auth_groups_add_member',{group_id:String(current.id),user_id:String(addUserId)},{headers:authHeaders()});setAddUserId('');loadMembers(current);reload();}catch(e){err(e);}};
 const removeMember=async uid=>{try{await api('auth_groups_remove_member',{group_id:String(current.id),user_id:String(uid)},{headers:authHeaders()});loadMembers(current);reload();}catch(e){err(e);}};
 return <div><div className="admin-form"><label>Название группы<input value={name} onChange={e=>setName(e.target.value)} placeholder="Группа 101"/></label><label>Описание<input value={desc} onChange={e=>setDesc(e.target.value)} placeholder="Необязательно"/></label><button className="admin-primary" disabled={!name.trim()} onClick={create}>Создать группу</button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Группа</th><th>Описание</th><th>Участников</th></tr></thead><tbody>{groups.map(g=><tr key={g.id} className={String(g.id)===selected?'selected':''} onClick={()=>loadMembers(g)}><td>{g.name}</td><td>{g.description||'—'}</td><td>{g.member_count||0}</td></tr>)}</tbody></table></div>{current&&<section><h3>Участники: {current.name}</h3><div className="admin-inline-actions"><select value={addUserId} onChange={e=>setAddUserId(e.target.value)}><option value="">Добавить участника…</option>{users.filter(u=>!members||!members.some(m=>m.id===u.id)).map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select><button onClick={addMember} disabled={!addUserId}>Добавить</button><button className="danger" onClick={removeGroup}>Удалить группу</button></div><ul className="admin-member-list">{(members||[]).map(m=><li key={m.id}><span>{m.full_name||m.login}</span><small>{ROLE_LABEL[m.role]||m.role}</small><button onClick={()=>removeMember(m.id)}>×</button></li>)}</ul></section>}</div>;
}

function UsersDrawer({model,onClose}){
 const [tab,setTab]=useState('users'),[search,setSearch]=useState(''),[role,setRole]=useState(''),[selected,setSelected]=useState(model.users[0]?.id||''),[users,setUsers]=useState(model.users),[groups,setGroups]=useState(model.groups||[]),[add,setAdd]=useState(false),[notice,setNotice]=useState('');
 const list=users.filter(u=>(!search||(u.name+' '+u.login).toLowerCase().includes(search.toLowerCase()))&&(!role||u.role===role));const current=users.find(u=>u.id===selected)||list[0];
 const reload=async()=>{try{const [us,gs]=await Promise.all([api('auth_users_list',{}, {headers:authHeaders()}),api('auth_groups_list',{}, {headers:authHeaders()})]);setUsers(legacyUsers(us));setGroups(gs);setNotice('Обновлено.');}catch(e){setNotice(String(e.message||e));}};
 const update=patch=>{const next=users.map(u=>u.id===current.id?{...u,...patch}:u);setUsers(next);const body={};const merged={...current,...patch};if('name' in patch)body.full_name=merged.name;if('role' in patch)body.role=ROLE_KEY[merged.role]||'student';if('status' in patch)body.is_active=merged.status!=='Заблокирован';if(Object.keys(body).length)api('auth_users_update',{user_id:String(current.id),...body},{headers:authHeaders()}).then(()=>setNotice('Сохранено.')).catch(e=>setNotice(String(e.message||e)));};
 return <Drawer title="Пользователи и доступ" onClose={onClose}><Tabs value={tab} onChange={setTab} items={[["users","Пользователи"],["groups","Группы"],["passwords","Сброс паролей"],["roles","Роли"],["audit","Аудит"]]}/>{notice&&<p className="admin-note">{notice}</p>}{tab==='groups'?<GroupPanel groups={groups} users={users} reload={reload} err={e=>setNotice(String(e.message||e))}/>:tab==='passwords'?<ResetPasswordsPanel users={users} groups={groups}/>:tab==='users'?<><Toolbar search={search} setSearch={setSearch}><select value={role} onChange={e=>setRole(e.target.value)}><option value="">Все роли</option><option>Администратор</option><option>Преподаватель</option><option>Обучающийся</option></select><button onClick={reload}>Обновить</button><button className="admin-primary" onClick={()=>setAdd(true)}>Добавить пользователя</button></Toolbar><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>ФИО</th><th>Логин</th><th>Роль</th><th>Статус</th></tr></thead><tbody>{list.map(u=><tr key={u.id} className={u.id===current?.id?'selected':''} onClick={()=>setSelected(u.id)}><td>{u.name}</td><td>{u.login||'—'}</td><td>{u.role}</td><td><Dot tone={u.status==='Заблокирован'?'red':'green'}/>{u.status}</td></tr>)}</tbody></table></div>{current&&<div className="admin-detail-grid"><section><h3>Основная информация</h3><label>ФИО<input value={current.name} onChange={e=>update({name:e.target.value})}/></label><label>Логин<div className="admin-static">{current.login||'—'}</div></label><label>Роль<select value={current.role} onChange={e=>update({role:e.target.value})}><option>Администратор</option><option>Преподаватель</option><option>Обучающийся</option></select></label><div className="admin-inline-actions"><button onClick={()=>update({status:current.status==='Заблокирован'?'Активен':'Заблокирован'})}>{current.status==='Заблокирован'?'Разблокировать':'Заблокировать'}</button><button className="danger" disabled={current.role==='Администратор'} onClick={()=>{if(!confirm('Удалить пользователя «'+current.name+'»?'))return;api('auth_users_delete',{user_id:String(current.id)},{headers:authHeaders()}).then(()=>{const next=users.filter(x=>x.id!==current.id);setUsers(next);setSelected(next[0]?.id||'');setNotice('Пользователь удалён.');}).catch(e=>setNotice(String(e.message||e)));}}>Удалить</button></div></section><section><h3>Права доступа</h3>{['trainings','scenarios','cards','results','users','monitoring'].map(p=><label className="admin-check" key={p}><input type="checkbox" checked={(current.permissions||[]).includes(p)} onChange={e=>update({permissions:e.target.checked?[...(current.permissions||[]),p]:(current.permissions||[]).filter(x=>x!==p)})}/><span>{{trainings:'Управление тренировками',scenarios:'Доступ к сценариям',cards:'Работа с карточками',results:'Просмотр результатов',users:'Управление пользователями',monitoring:'Мониторинг системы'}[p]}</span></label>)}</section></div>}</>:tab==='roles'?<RoleMatrix/>:<AuditList/>}{add&&<AddUser onClose={()=>setAdd(false)} onAdd={u=>{setUsers([u,...users]);setSelected(u.id);setAdd(false);}}/>}</Drawer>;
}
function ResetPasswordsPanel({users,groups}){
 const students=users.filter(u=>u.role==='Обучающийся'),[groupId,setGroupId]=useState(''),[selected,setSelected]=useState([]),[sharedPassword,setSharedPassword]=useState(''),[credentials,setCredentials]=useState([]),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const groupMode=groupId!=='';
 const toggleStudent=id=>setSelected(ids=>ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]);
 const reset=async()=>{
  if(busy)return;
  if(!groupMode&&!selected.length)return;
  if(!confirm('Сбросить пароли выбранных обучающихся? Действие нельзя отменить.'))return;
  setBusy(true);setError('');setCredentials([]);
  try{
   const params=groupMode?{group_id:groupId}:{user_ids:selected.map(Number)};
   if(sharedPassword)params.password=sharedPassword;
   const result=await api('auth_users_reset_passwords',params,{headers:authHeaders()});
   if(!Array.isArray(result))throw new Error('Сервер вернул неожиданный формат результата.');
   setCredentials(result);setSharedPassword('');setSelected([]);
  }catch(e){setError(String(e.message||e));}
  finally{setBusy(false);}
 };
 const download=format=>{
  const columns=['user_id','login','display_name','password'];
  const safe=(value,key)=>{let text=String(value??'');if(key!=='password'&&/^\s*[=+\-@]/.test(text))text="'"+text;return text;};
  const quote=(value,key)=>'"'+safe(value,key).replace(/"/g,'""')+'"';
  const lines=[columns.map(key=>quote(key,key)).join(format==='csv'?',':'\t'),...credentials.map(row=>columns.map(key=>quote(row[key],key)).join(format==='csv'?',':'\t'))];
  const blob=new Blob(['\uFEFF'+lines.join(format==='csv'?'\r\n':'\n')],{type:format==='csv'?'text/csv;charset=utf-8':'text/plain;charset=utf-8'});
  const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`student-passwords.${format}`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);
 };
 return <div><section><h3>Массовый сброс</h3><p className="admin-muted">Выберите учебную группу или отметьте обучающихся. Сформированные пароли показываются только в этом окне и не сохраняются.</p><div className="admin-form"><label>Учебная группа<select value={groupId} onChange={e=>{setGroupId(e.target.value);setSelected([]);}}><option value="">Выбрать обучающихся вручную</option>{groups.map(g=><option key={g.id} value={String(g.id)}>{g.name}</option>)}</select></label><label>Общий пароль (необязательно)<input type="password" autoComplete="new-password" value={sharedPassword} onChange={e=>setSharedPassword(e.target.value)} placeholder="Оставьте пустым для генерации"/></label></div>{!groupMode&&<><div className="admin-inline-actions"><button type="button" onClick={()=>setSelected(students.map(u=>u.id))} disabled={!students.length}>Выбрать всех обучающихся</button><button type="button" onClick={()=>setSelected([])} disabled={!selected.length}>Снять выделение</button><span>{selected.length} выбрано</span></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Выбор</th><th>ФИО</th><th>Логин</th><th>ID</th></tr></thead><tbody>{students.map(u=><tr key={u.id}><td><input type="checkbox" aria-label={`Выбрать ${u.name}`} checked={selected.includes(u.id)} onChange={()=>toggleStudent(u.id)}/></td><td>{u.name}</td><td>{u.login||'—'}</td><td>{u.id}</td></tr>)}</tbody></table></div></>}{groupMode&&<p className="admin-muted">Пароли будут сброшены всем обучающимся в группе «{groups.find(g=>String(g.id)===groupId)?.name||groupId}».</p>}{sharedPassword&&sharedPassword.length<6&&<p className="admin-login-error" role="alert">Пароль должен содержать не менее 6 символов.</p>}{error&&<p className="admin-login-error" role="alert">{error}</p>}<button className="admin-primary" disabled={busy||(!groupMode&&!selected.length)||(!!sharedPassword&&sharedPassword.length<6)} onClick={reset}>{busy?'Выполняется сброс…':'Сбросить пароли'}</button></section>{credentials.length>0&&<section><h3>Временные пароли ({credentials.length})</h3><p className="admin-note" role="status">Скопируйте или экспортируйте пароли сейчас. Они не будут доступны после закрытия панели.</p><div className="admin-inline-actions"><button onClick={()=>download('csv')}>Экспорт CSV</button><button onClick={()=>download('txt')}>Экспорт TXT</button><button className="danger" onClick={()=>setCredentials([])}>Удалить пароли с экрана</button></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>User ID</th><th>Логин</th><th>Имя</th><th>Одноразовый пароль</th></tr></thead><tbody>{credentials.map(row=><tr key={row.user_id}><td>{row.user_id}</td><td>{row.login}</td><td>{row.display_name}</td><td><code>{row.password}</code></td></tr>)}</tbody></table></div></section>}</div>;
}
function AddUser({onClose,onAdd}){const [name,setName]=useState(''),[login,setLogin]=useState(''),[password,setPassword]=useState(''),[role,setRole]=useState('student'),[error,setError]=useState('');const submit=async()=>{try{const u=await api('auth_users_create',{login:login.trim(),password,full_name:name.trim(),role},{headers:authHeaders()});onAdd(legacyUsers([u])[0]);}catch(e){setError(e.message||'Ошибка.');}};return <Modal title="Добавить пользователя" onClose={onClose}><div className="admin-form"><label>ФИО<input value={name} onChange={e=>setName(e.target.value)} placeholder="Иванов И.И."/></label><label>Логин<input value={login} onChange={e=>setLogin(e.target.value.toLowerCase())} placeholder="ivanov"/></label><label>Пароль<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="минимум 6 символов"/></label><label>Роль<select value={role} onChange={e=>setRole(e.target.value)}><option value="student">Обучающийся</option><option value="teacher">Преподаватель</option><option value="admin">Администратор</option></select></label>{error&&<p className="admin-login-error" role="alert">{error}</p>}<button className="admin-primary" disabled={!name.trim()||login.trim().length<3||password.length<6} onClick={submit}>Создать пользователя</button></div></Modal>}
function RoleMatrix(){return <div className="admin-info-cards"><section><h3>Администратор</h3><p>Полный доступ: пользователи, контент, результаты, мониторинг и настройки.</p></section><section><h3>Преподаватель</h3><p>Создание сценариев и карточек, назначение тренировок и проверка результатов.</p></section><section><h3>Обучающийся</h3><p>Доступ только к назначенным тренировкам и собственным результатам.</p></section></div>}
function AuditList(){return <div className="admin-events"><p>Журнал действий пользователей подключается вместе с серверной авторизацией команды. Демонстрационные события здесь не показываются.</p></div>}

function TrainingsDrawer({model,onClose}){const [search,setSearch]=useState(''),[selected,setSelected]=useState(''),[detail,setDetail]=useState(null);const list=model.trainings.filter(t=>!search||t.title.toLowerCase().includes(search.toLowerCase()));const current=model.trainings.find(t=>t.id===selected)||list[0];return <Drawer title="Тренировки" onClose={onClose}><Tabs value="all" onChange={()=>{}} items={[["all","Все"],["active","Активные"],["done","Завершенные"]]}/><Toolbar search={search} setSearch={setSearch}><button className="admin-primary" onClick={()=>location.assign('/teacher#create-training')}>Создать тренировку</button></Toolbar><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Название</th><th>Преподаватель</th><th>Обучающиеся</th><th>Режим</th><th>Статус</th></tr></thead><tbody>{list.map(t=><tr key={t.id} onClick={()=>setSelected(t.id)} className={t.id===current?.id?'selected':''}><td>{t.title}</td><td>{t.teacher}</td><td>{t.students}</td><td>{t.mode}</td><td><Dot tone={t.status==='Активна'?'green':'gray'}/>{t.status}</td></tr>)}</tbody></table></div>{current?<div className="admin-three"><section><h3>Параметры тренировки</h3><p><b>Название</b><span>{current.title}</span></p><p><b>Группа</b><span>{current.group}</span></p><p><b>Режим</b><span>{current.mode}</span></p><p><b>Статус</b><span>{current.status}</span></p><button onClick={()=>setDetail(current)}>Открыть</button></section><section><h3>Назначенные участники ({current.students})</h3>{[...new Set(current.sessions.map(s=>s.student))].slice(0,9).map(x=><p key={x}>♙ {x}</p>)}</section><section><h3>Ход выполнения</h3><p>Активно: {current.sessions.filter(s=>s.status==='active').length}</p><p>На проверке: {current.sessions.filter(s=>['submitted','pending_teacher'].includes(s.status)).length}</p><p>Завершено: {current.sessions.filter(s=>s.status==='reviewed').length}</p></section></div>:<Empty/>}{detail&&<Modal title={detail.title} onClose={()=>setDetail(null)}><p>{detail.sessions.length} учебных работ.</p><div className="admin-mini-list">{detail.sessions.map(s=><p key={s.id}><span>{s.student}</span><b>{statusLabel[s.status]||s.status}</b></p>)}</div></Modal>}</Drawer>}

function ScenariosDrawer({model,onClose}){const [search,setSearch]=useState(''),[selected,setSelected]=useState('');const list=model.scenarios.filter(x=>!search||(x.title||'').toLowerCase().includes(search.toLowerCase()));const current=model.scenarios.find(x=>x.id===selected)||list[0];return <Drawer title="Сценарии" onClose={onClose}><Tabs value="scenarios" onChange={()=>{}} items={[["scenarios","Сценарии"],["categories","Категории"],["groups","Группы событий"]]}/><Toolbar search={search} setSearch={setSearch}><button className="admin-primary" onClick={()=>location.assign('/teacher#create-training')}>Добавить сценарий</button></Toolbar><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Название</th><th>Категория</th><th>Карточек</th><th>Режим</th><th>Обновлён</th></tr></thead><tbody>{list.map(x=><tr key={x.id} onClick={()=>setSelected(x.id)} className={x.id===current?.id?'selected':''}><td>{x.title||'Без названия'}</td><td>{x.category||'—'}</td><td>{x.task_ids?.length||0}</td><td>{x.mode==='testing'?'Тестирование':'Обучение'}</td><td>{fmt(x.updated_at||x.created_at)}</td></tr>)}</tbody></table></div>{current?<div className="admin-three"><section><h3>Основные параметры</h3><p><b>Название</b><span>{current.title}</span></p><p><b>Карточек</b><span>{current.task_ids?.length||0}</span></p><p><b>Группа</b><span>{current.group||'—'}</span></p><p><b>Локация</b><span>{current.location||'—'}</span></p></section><section><h3>Состав сценария</h3><p>{(current.assignment_task_ids||current.task_ids||[]).length} карточек выбрано для назначения.</p><p className="admin-muted">Каталог сценария хранится отдельно от конкретного запуска.</p></section><section><h3>Версия и изменения</h3><p><Dot/> Актуальная локальная версия</p><p className="admin-muted">Повторное назначение не изменяет исходный каталог.</p></section></div>:<Empty text="Сценарии пока не созданы"/>}</Drawer>}

function CardsDrawer({model,onClose}){const [search,setSearch]=useState(''),[selected,setSelected]=useState('');const list=model.cards.filter(c=>!search||(c.number+' '+c.content?.title).toLowerCase().includes(search.toLowerCase()));const current=model.cards.find(c=>c.id===selected)||list[0];return <Drawer title="Карточки происшествий" onClose={onClose}><Tabs value="cards" onChange={()=>{}} items={[["cards","Карточки"],["review","Проверка"],["archive","Архив"]]}/><Toolbar search={search} setSearch={setSearch}><button className="admin-primary" onClick={()=>location.assign('/cards')}>Открыть мастерскую</button></Toolbar><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>№ карточки</th><th>Название</th><th>Статус</th><th>Источник</th><th>Дата</th></tr></thead><tbody>{list.map(c=><tr key={c.id} className={c.id===current?.id?'selected':''} onClick={()=>setSelected(c.id)}><td>{c.number}</td><td>{c.content?.title}</td><td><Dot tone={c.status==='approved'?'green':'blue'}/>{c.status==='approved'?'Проверена':'Черновик'}</td><td>{['ai','gigachat'].includes(c.provenance?.source)?'ИИ':'Вручную'}</td><td>{fmt(c.updated_at)}</td></tr>)}</tbody></table></div>{current?<div className="admin-three"><section><h3>Сведения по карточке</h3><p><b>№</b><span>{current.number}</span></p><p><b>Тип</b><span>{current.content?.title}</span></p><p><b>Статус</b><span>{current.status}</span></p></section><section><h3>Классификация</h3><p>Кодов: {current.content?.class_ids?.length||0}</p><p>Служб: {current.content?.services?.length||0}</p><p>Главная служба: {current.content?.main_service||'—'}</p></section><section><h3>Последние действия</h3>{(current.history||[]).slice(-4).reverse().map((h,i)=><p key={i}><Dot tone="blue"/>{h.text}<small>{fmt(h.at)}</small></p>)}</section></div>:<Empty text="Карточки пока не созданы"/>}</Drawer>}

function ResultsDrawer({data,onClose}){const [tab,setTab]=useState('students'),[search,setSearch]=useState('');const rows=data.sessions.filter(s=>['submitted','pending_teacher','reviewed'].includes(s.status)&&(!search||(s.student+' '+s.title).toLowerCase().includes(search.toLowerCase())));const graded=rows.filter(x=>x.grade!=null),avg=graded.length?(graded.reduce((a,b)=>a+b.grade,0)/graded.length).toFixed(1):'—';return <Drawer title="Результаты" onClose={onClose}><Tabs value={tab} onChange={setTab} items={[["students","По обучающимся"],["trainings","По тренировкам"],["analytics","Аналитика"]]}/><Toolbar search={search} setSearch={setSearch}><button className="admin-primary" onClick={()=>location.assign('/teacher#results')}>Открыть проверку</button></Toolbar>{tab!=='analytics'?<><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Обучающийся</th><th>Тренировка</th><th>Результат</th><th>Статус</th><th>Дата</th></tr></thead><tbody>{rows.map(s=><tr key={s.id}><td>{s.student}</td><td>{s.title}</td><td>{s.grade?`${s.grade} / 5`:'—'}</td><td>{statusLabel[s.status]||s.status}</td><td>{fmt(s.updated_at||s.created_at)}</td></tr>)}</tbody></table></div><div className="admin-three"><section><h3>Сводка</h3><p><b>Всего работ</b><span>{rows.length}</span></p><p><b>Проверено</b><span>{graded.length}</span></p><p><b>Средняя оценка</b><span>{avg}</span></p></section><section><h3>Типовые состояния</h3><p><Dot tone="green"/> Завершено: {rows.filter(x=>x.status==='reviewed').length}</p><p><Dot tone="orange"/> Требует проверки: {rows.filter(x=>x.status!=='reviewed').length}</p></section><section><h3>Рекомендации ИИ</h3><p>Используйте предварительную проверку в панели преподавателя, а итоговое решение подтверждайте вручную.</p></section></div></>:<Analytics rows={rows}/>}</Drawer>}
function Analytics({rows}){const grouped=[...new Map(rows.map(x=>[x.student,[]]))];rows.forEach(x=>grouped.find(([k])=>k===x.student)?.[1].push(x));return <div className="admin-analytics"><h3>Сводка по обучающимся</h3>{grouped.map(([name,list])=><div key={name}><b>{name}</b><span>{list.length} работ</span><progress value={list.filter(x=>x.status==='reviewed').length} max={Math.max(1,list.length)}/></div>)}</div>}

function MonitoringDrawer({data,onClose}){const [tab,setTab]=useState('ai'),[checked,setChecked]=useState({state:'unchecked',message:'Не проверен'});const check=async()=>{setChecked({state:'checking',message:'Проверка…'});try{const result=await api('ai_status');setChecked({state:result.state||'available',message:result.message||'API отвечает'});}catch(e){setChecked({state:'error',message:e.message});}};const tone=checked.state==='available'?'green':checked.state==='error'?'red':'gray';return <Drawer title="Мониторинг" onClose={onClose}><Tabs value={tab} onChange={setTab} items={[["components","Компоненты"],["ai","ИИ"],["events","События"]]}/>{tab==='components'?<div className="admin-monitor-list">{[['Локальный сервер',data.error?'Ошибка':'Доступен'],['ИИ-модуль',checked.state==='available'?'Доступен':checked.state==='error'?'Ошибка':checked.state==='configured'?'Настроен':'Не проверен'],['Хранилище карточек','Не проверено'],['Учебные сессии',data.error?'Ошибка':'Данные получены'],['Интерфейс','Открыт']].map(([a,b])=><p key={a}><span>{a}</span><b><Dot tone={b==='Нормально'||b==='Доступен'?'green':b==='Ошибка'?'red':'gray'}/>{b}</b></p>)}</div>:tab==='ai'?<><section className="admin-llm-card"><header><h3>ИИ-сервис</h3><span><Dot tone={tone}/> подключение настраивается локальным ключом</span></header><div className="admin-llm-row"><div><b>Внешний ИИ</b><small>API-подключение</small></div><div><b>Статус</b><span><Dot tone={tone}/>{checked.state==='available'?'API отвечает':checked.state==='configured'?'Настроен':checked.state==='error'?'Ошибка':checked.message}</span></div><button disabled={checked.state==='checking'} onClick={check}>Проверить ИИ</button></div>{['available','configured','error'].includes(checked.state)&&<p className="admin-note">{checked.message}</p>}</section><section className="admin-llm-card"><h3>Параметры подключения</h3><p>Ключ ИИ хранится в <code>config.local.json</code> на текущем компьютере и не включён в передаваемый ZIP.</p><p>Выберите провайдера, API-ключ и модель через <code>CHANGE_AI_KEY.cmd</code>, затем перезапустите приложение. Для GigaChat при ошибке сертификата используйте <code>PREPARE_AI_CONNECTION.cmd</code>.</p><button onClick={()=>alert('Откройте CHANGE_AI_KEY.cmd в папке программы, выберите провайдера и введите API-ключ. Сохраните настройки и перезапустите приложение.')}>Как изменить ключ</button></section></>:<div className="admin-events"><p><Dot tone="blue"/><strong>Мониторинг открыт</strong><span>сейчас</span></p><p><Dot/><strong>Сервер интерфейса отвечает</strong><span>сейчас</span></p></div>}</Drawer>}

function SystemDrawer({model,onClose}){const [confirm,setConfirm]=useState(false);return <Drawer title="Управление системой" onClose={onClose}><div className="admin-system-grid"><section><h3>Состояние данных</h3><p><b>Пользователей</b><span>{model.users.length}</span></p><p><b>Сценариев</b><span>{model.scenarios.length}</span></p><p><b>Карточек</b><span>{model.cards.length}</span></p><p><b>Тренировок</b><span>{model.trainings.length}</span></p></section><section><h3>Обслуживание</h3><button onClick={()=>location.reload()}>Обновить интерфейс</button><button onClick={()=>setConfirm(true)}>Очистить локальный кэш интерфейса</button><button onClick={()=>alert('Используйте RESTART.cmd из папки программы.')}>Перезапустить сервер</button></section><section><h3>Экспорт</h3><button onClick={()=>{const blob=new Blob([JSON.stringify({users:model.users,scenarios:model.scenarios,cards:model.cards},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='admin-export.json';a.click();}}>Экспорт локальных данных</button></section></div>{confirm&&<Modal title="Очистить только кэш интерфейса?" onClose={()=>setConfirm(false)}><p>Учебные карточки и сценарии останутся. Будут очищены только временные настройки административных таблиц.</p><button className="admin-primary" onClick={()=>{sessionStorage.clear();location.assign('/admin-login');}}>Продолжить</button></Modal>}</Drawer>}

function SettingsDrawer({onClose}){const [tab,setTab]=useState('general'),[name,setName]=useState(localStorage.getItem('giik.system.name')||'ИИ-тренажёр 112'),[notice,setNotice]=useState('');return <Drawer title="Настройки" onClose={onClose}><Tabs value={tab} onChange={setTab} items={[["general","Общие"],["security","Безопасность"],["integrations","Интеграции"],["notifications","Уведомления"]]}/>{tab==='general'?<div className="admin-settings"><label>Название системы<input value={name} onChange={e=>setName(e.target.value)}/></label><label>Часовой пояс<select><option>Системный часовой пояс</option><option>UTC+3 Москва</option><option>UTC+7 Красноярск</option></select></label><label>Язык интерфейса<select><option>Русский</option></select></label><label>Формат даты<select><option>ДД.ММ.ГГГГ</option></select></label><button className="admin-primary admin-wide" onClick={()=>{localStorage.setItem('giik.system.name',name);setNotice('Настройки сохранены.');}}>Сохранить изменения</button>{notice&&<p className="admin-note">{notice}</p>}</div>:<ToggleSettings tab={tab}/>}</Drawer>}
function ToggleSettings({tab}){return <div className="admin-toggle-list"><p>Настройки безопасности, базы данных и системных уведомлений подключаются к серверу команды. Локальные переключатели не меняют работу системы.</p></div>}

/* ---------------- Справочники (Этап 2.2) ---------------- */
function useCatalog(action,params={}){
 const [rows,setRows]=useState([]);
 useEffect(()=>{let alive=true;api(action,params,{headers:authHeaders()}).then(x=>alive&&setRows(x)).catch(()=>{});return()=>{alive=false;};},[action]);
 const refresh=async()=>{const x=await api(action,params,{headers:authHeaders()});setRows(x);return x;};
 return [rows,refresh];
}
const catSlice=(rows,limit=400)=>({visible:rows.slice(0,limit),total:rows.length});
function CatalogTable({cols,rows,selected,onSelect,empty='Записей пока нет'}){
 const {visible,total}=catSlice(rows);
 return <><div className="admin-table-wrap">{visible.length?<table className="admin-table"><thead><tr>{cols.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{visible.map((r,i)=><tr key={r._k||i} className={selected===r._k?'selected':''} onClick={()=>onSelect(r)}><td>{cols[0]?r[cols[0].key]:''}</td>{cols.slice(1).map(c=><td key={c.key}>{c.render?c.render(r[c.key],r):String(r[c.key]??'—')}</td>)}</tr>)}</tbody></table>:<Empty text={empty}/>}</div>{total>400&&<p className="admin-muted">Показаны первые 400 из {total} записей. Используйте поиск для фильтрации.</p>}</>;
}
function ServicePanel(){
 const [rows,reload]=useCatalog('catalog_services_list'),[error,setError]=useState('');
 const [search,setSearch]=useState(''),[sel,setSel]=useState(''),[code,setCode]=useState(''),[name,setName]=useState(''),[edit,setEdit]=useState('');
 const list=rows.filter(r=>!search||(r.code+' '+r.name).toLowerCase().includes(search.toLowerCase()));
 const current=rows.find(r=>r.code===sel)||null;
 const call=async fn=>{try{await fn();reload();setError('');}catch(e){setError(String(e?.message||e));}};
 return <><Toolbar search={search} setSearch={setSearch}><button onClick={()=>reload().catch(e=>setError(String(e?.message||e)))}>Обновить</button></Toolbar><div className="admin-form"><label>Код<input value={code} onChange={e=>setCode(e.target.value)} placeholder="105"/></label><label>Название<input value={name} onChange={e=>setName(e.target.value)} placeholder="Служба"/></label><button className="admin-primary" disabled={!code.trim()||!name.trim()} onClick={()=>call(()=>api('catalog_services_create',{code:code.trim(),name:name.trim()},{headers:authHeaders()})).then(()=>{setCode('');setName('');})}>Добавить службу</button></div><CatalogNotice error={error}/><CatalogTable cols={[{key:'code',label:'Код'},{key:'name',label:'Название'}]} rows={list.map(r=>({...r,_k:r.code}))} selected={sel} onSelect={r=>{setSel(r.code);setEdit(r.name);}}/><div className="admin-muted">{list.length} служб</div>{current&&<section><h3>Правка: {current.code}</h3><div className="admin-inline-actions"><input value={edit} onChange={e=>setEdit(e.target.value)}/><button className="admin-primary" disabled={!edit.trim()} onClick={()=>call(()=>api('catalog_services_update',{service_code:current.code,name:edit.trim()},{headers:authHeaders()}))}>Сохранить</button><button className="danger" onClick={()=>{if(confirm('Удалить службу «'+current.name+'»?'))call(()=>api('catalog_services_delete',{service_code:current.code},{headers:authHeaders()})).then(()=>setSel(''));}}>Удалить</button></div></section>}</>;
}
function CategoryPanel(){
 const [rows,reload]=useCatalog('catalog_categories_list'),[error,setError]=useState('');
 const [search,setSearch]=useState(''),[sel,setSel]=useState(''),[cid,setCid]=useState(''),[name,setName]=useState(''),[edit,setEdit]=useState('');
 const list=rows.filter(r=>!search||(r.id+' '+r.name).toLowerCase().includes(search.toLowerCase()));
 const current=rows.find(r=>String(r.id)===String(sel))||null;
 const call=async fn=>{try{await fn();reload();setError('');}catch(e){setError(String(e?.message||e));}};
 return <><Toolbar search={search} setSearch={setSearch}><button onClick={()=>reload().catch(e=>setError(String(e?.message||e)))}>Обновить</button></Toolbar><div className="admin-form"><label>№<input value={cid} onChange={e=>setCid(e.target.value.replace(/\D/g,''))} placeholder="25"/></label><label>Название<input value={name} onChange={e=>setName(e.target.value)}/></label><button className="admin-primary" disabled={!cid.trim()||!name.trim()} onClick={()=>call(()=>api('catalog_categories_create',{category_id:cid.trim(),name:name.trim()},{headers:authHeaders()})).then(()=>{setCid('');setName('');})}>Добавить категорию</button></div><CatalogNotice error={error}/><CatalogTable cols={[{key:'id',label:'№'},{key:'name',label:'Название'}]} rows={list.map(r=>({...r,_k:String(r.id)}))} selected={String(sel)} onSelect={r=>{setSel(String(r.id));setEdit(r.name);}}/><div className="admin-muted">{list.length} категорий</div>{current&&<section><h3>Правка категории №{current.id}</h3><div className="admin-inline-actions"><input value={edit} onChange={e=>setEdit(e.target.value)}/><button className="admin-primary" disabled={!edit.trim()} onClick={()=>call(()=>api('catalog_categories_update',{category_id:String(current.id),name:edit.trim()},{headers:authHeaders()}))}>Сохранить</button><button className="danger" onClick={()=>{if(confirm('Удалить категорию №'+current.id+'?'))call(()=>api('catalog_categories_delete',{category_id:String(current.id)},{headers:authHeaders()})).then(()=>setSel(''));}}>Удалить</button></div></section>}</>;
}
function EntryPanel(){
 const [rows,reload]=useCatalog('catalog_entries_list'),[cats]=useCatalog('catalog_categories_list'),[services]=useCatalog('catalog_services_list');
 const [error,setError]=useState('');
 const [search,setSearch]=useState(''),[filterCat,setFilterCat]=useState(''),[sel,setSel]=useState('');
 const [eid,setEid]=useState(''),[ecat,setEcat]=useState(''),[etitle,setEtitle]=useState('');
 const [edit,setEdit]=useState(null);
 const list=rows.filter(r=>(!search||[r.id,r.title,r.group_name,r.statistical_group].join(' ').toLowerCase().includes(search.toLowerCase()))&&(!filterCat||String(r.category_id)===String(filterCat)));
 const current=rows.find(r=>r.id===sel)||null;
 const call=async fn=>{try{await fn();reload();setError('');}catch(e){setError(String(e?.message||e));}};
 const field=(k,l,value,onChange)=> <label>{l}<input value={value} onChange={e=>onChange(e.target.value)}/></label>;
 const create=()=>{if(!eid.trim()||!ecat||!etitle.trim())return;call(()=>api('catalog_entries_create',{entry_id:eid.trim(),category_id:String(ecat),title:etitle.trim()},{headers:authHeaders()})).then(()=>{setEid('');setEtitle('');});};
 const save=()=>{if(!current||!edit)return;const body={};Object.keys(edit).forEach(k=>{if(k!=='id'&&k!=='category_id'&&k!=='main_service_code')body[k]=edit[k];});body.category_id=String(edit.category_id);if(edit.main_service_code)body.main_service_code=edit.main_service_code;call(()=>api('catalog_entries_update',{entry_id:current.id,...body},{headers:authHeaders()}));};
 return <><Toolbar search={search} setSearch={setSearch}><select value={filterCat} onChange={e=>setFilterCat(e.target.value)}><option value="">Все категории</option>{cats.map(c=><option key={c.id} value={String(c.id)}>{c.id} — {c.name}</option>)}</select><button onClick={()=>reload().catch(e=>setError(String(e?.message||e)))}>Обновить</button></Toolbar><div className="admin-form"><label>Код<input value={eid} onChange={e=>setEid(e.target.value)} placeholder="1010101"/></label><label>Категория<select value={String(ecat)} onChange={e=>setEcat(e.target.value)}><option value="">Выберите…</option>{cats.map(c=><option key={c.id} value={String(c.id)}>{c.id} — {c.name}</option>)}</select></label><label>Название<input value={etitle} onChange={e=>setEtitle(e.target.value)}/></label><button className="admin-primary" disabled={!eid.trim()||!ecat||!etitle.trim()} onClick={create}>Добавить запись</button></div><CatalogNotice error={error}/><CatalogTable cols={[{key:'id',label:'Код'},{key:'category_id',label:'Кат.'},{key:'title',label:'Название'},{key:'group_name',label:'Группа'}]} rows={list.map(r=>({...r,_k:r.id}))} selected={sel} onSelect={r=>{setSel(r.id);setEdit({...r});}}/><div className="admin-muted">{list.length} записей</div>{current&&edit&&<section><h3>Правка записи {current.id}</h3><div className="admin-form">{field('group_name','Группа',edit.group_name,v=>setEdit({...edit,group_name:v}))}{field('statistical_group','Стат. группа',edit.statistical_group,v=>setEdit({...edit,statistical_group:v}))}{field('sign1','Признак 1',edit.sign1,v=>setEdit({...edit,sign1:v}))}{field('sign2','Признак 2',edit.sign2,v=>setEdit({...edit,sign2:v}))}{field('sign3','Признак 3',edit.sign3,v=>setEdit({...edit,sign3:v}))}{field('extra_signs','Доп. признаки',edit.extra_signs,v=>setEdit({...edit,extra_signs:v}))}{field('title','Название',edit.title,v=>setEdit({...edit,title:v}))}{field('ekp_type','Тип ЕКП',edit.ekp_type,v=>setEdit({...edit,ekp_type:v}))}<label>Категория<select value={String(edit.category_id)} onChange={e=>setEdit({...edit,category_id:e.target.value})}>{cats.map(c=><option key={c.id} value={String(c.id)}>{c.id} — {c.name}</option>)}</select></label><label>Главная служба<select value={String(edit.main_service_code||'')} onChange={e=>setEdit({...edit,main_service_code:e.target.value})}><option value="">—</option>{services.map(s=><option key={s.code} value={s.code}>{s.code} — {s.name}</option>)}</select></label></div><div className="admin-inline-actions"><button className="admin-primary" onClick={save}>Сохранить</button><button className="danger" onClick={()=>{if(confirm('Удалить запись «'+current.id+'»?'))call(()=>api('catalog_entries_delete',{entry_id:current.id},{headers:authHeaders()})).then(()=>setSel(''));}}>Удалить</button></div></section>}</>;
}
function LinkPanel(){
 const [rows,reload]=useCatalog('catalog_entry_services_list'),[services]=useCatalog('catalog_services_list');
 const [error,setError]=useState('');
 const [search,setSearch]=useState(''),[sel,setSel]=useState('');
 const [lid,setLid]=useState(''),[lservice,setLservice]=useState(''),[lcond,setLcond]=useState(''),[lvalue,setLvalue]=useState('');
 const [edit,setEdit]=useState(null);
 const list=rows.filter(r=>!search||[r.entry_id,r.service_code,r.condition_text,r.value].join(' ').toLowerCase().includes(search.toLowerCase()));
 const current=rows.find(r=>String(r.id)===String(sel))||null;
 const call=async fn=>{try{await fn();reload();setError('');}catch(e){setError(String(e?.message||e));}};
 const create=()=>{if(!lid.trim()||!lservice)return;call(()=>api('catalog_entry_services_create',{entry_id:lid.trim(),service_code:lservice},{headers:authHeaders()})).then(()=>{setLid('');setLvalue('');});};
 const save=()=>{if(!current||!edit)return;const body={...edit};delete body.id;delete body.entry_id;if(body.service_code)body.service_code=String(body.service_code);body.is_main=!!body.is_main;call(()=>api('catalog_entry_services_update',{entry_service_id:String(current.id),...body},{headers:authHeaders()}));};
 return <><Toolbar search={search} setSearch={setSearch}><button onClick={()=>reload().catch(e=>setError(String(e?.message||e)))}>Обновить</button></Toolbar><div className="admin-form"><label>Код записи<input value={lid} onChange={e=>setLid(e.target.value)} placeholder="1010101"/></label><label>Служба<select value={lservice} onChange={e=>setLservice(e.target.value)}><option value="">Выберите…</option>{services.map(s=><option key={s.code} value={s.code}>{s.code} — {s.name}</option>)}</select></label><label>Условие<input value={lcond} onChange={e=>setLcond(e.target.value)}/></label><label>Значение<input value={lvalue} onChange={e=>setLvalue(e.target.value)}/></label><button className="admin-primary" disabled={!lid.trim()||!lservice} onClick={create}>Добавить связь</button></div><CatalogNotice error={error}/><CatalogTable cols={[{key:'id',label:'ID'},{key:'entry_id',label:'Запись'},{key:'service_code',label:'Служба'},{key:'condition_text',label:'Условие'},{key:'value',label:'Значение'},{key:'is_main',label:'Основная',render:v=>(v?'да':'—')}]} rows={list.map(r=>({...r,_k:String(r.id)}))} selected={String(sel)} onSelect={r=>{setSel(String(r.id));setEdit({...r});}}/><div className="admin-muted">{list.length} связей</div>{current&&edit&&<section><h3>Правка связи №{current.id}</h3><div className="admin-form"><label>Код записи<div className="admin-static">{current.entry_id}</div></label><label>Служба<select value={String(edit.service_code)} onChange={e=>setEdit({...edit,service_code:e.target.value})}>{services.map(s=><option key={s.code} value={s.code}>{s.code} — {s.name}</option>)}</select></label><label>Тип условия<input value={edit.condition_type||''} onChange={e=>setEdit({...edit,condition_type:e.target.value})}/></label><label>Условие<input value={edit.condition_text||''} onChange={e=>setEdit({...edit,condition_text:e.target.value})}/></label><label>Значение<input value={edit.value||''} onChange={e=>setEdit({...edit,value:e.target.value})}/></label><label className="admin-check-label"><input type="checkbox" checked={!!edit.is_main} onChange={e=>setEdit({...edit,is_main:e.target.checked})}/> Основная служба</label></div><div className="admin-inline-actions"><button className="admin-primary" onClick={save}>Сохранить</button><button className="danger" onClick={()=>{if(confirm('Удалить связь №'+current.id+'?'))call(()=>api('catalog_entry_services_delete',{entry_service_id:String(current.id)},{headers:authHeaders()})).then(()=>setSel(''));}}>Удалить</button></div></section>}</>;
}
function AddressPanel(){
 const [rows,reload]=useCatalog('catalog_geo_addresses_list',{limit:1000});
 const [error,setError]=useState('');
 const [search,setSearch]=useState(''),[filterKind,setFilterKind]=useState(''),[sel,setSel]=useState('');
 const [aid,setAid]=useState(''),[astreet,setAstreet]=useState('');
 const [edit,setEdit]=useState(null);
 const list=rows.filter(r=>(!search||(r.street+' '+r.house+' '+r.id).toLowerCase().includes(search.toLowerCase()))&&(!filterKind||r.kind===filterKind));
 const current=rows.find(r=>r.id===sel)||null;
 const call=async fn=>{try{await fn();reload();setError('');}catch(e){setError(String(e?.message||e));}};
 const create=()=>{if(!aid.trim()||!astreet.trim())return;call(()=>api('catalog_geo_addresses_create',{address_id:aid.trim(),street:astreet.trim()},{headers:authHeaders()})).then(()=>{setAid('');setAstreet('');});};
 const save=()=>{if(!current||!edit)return;const body={};['street','house','kind'].forEach(k=>{if(edit[k]!==undefined)body[k]=edit[k];});if(edit.lat!==''&&edit.lat!=null)body.lat=Number(edit.lat);if(edit.lon!==''&&edit.lon!=null)body.lon=Number(edit.lon);call(()=>api('catalog_geo_addresses_update',{address_id:current.id,...body},{headers:authHeaders()}));};
 return <><Toolbar search={search} setSearch={setSearch}><select value={filterKind} onChange={e=>setFilterKind(e.target.value)}><option value="">Все виды</option><option value="building">Здания</option><option value="street">Улицы</option></select><button onClick={()=>reload().catch(e=>setError(String(e?.message||e)))}>Обновить</button></Toolbar><div className="admin-form"><label>ID<input value={aid} onChange={e=>setAid(e.target.value)} placeholder="building-…"/></label><label>Улица<input value={astreet} onChange={e=>setAstreet(e.target.value)}/></label><button className="admin-primary" disabled={!aid.trim()||!astreet.trim()} onClick={create}>Добавить адрес</button></div><CatalogNotice error={error}/><CatalogTable cols={[{key:'id',label:'ID'},{key:'street',label:'Улица'},{key:'house',label:'Дом'},{key:'kind',label:'Вид'},{key:'lat',label:'Широта',render:v=>v??'—'},{key:'lon',label:'Долгота',render:v=>v??'—'}]} rows={list.map(r=>({...r,_k:r.id}))} selected={sel} onSelect={r=>{setSel(r.id);setEdit({...r,lat:String(r.lat??''),lon:String(r.lon??'')});}}/><div className="admin-muted">{list.length} адресов (из {rows.length} загруженных)</div>{current&&edit&&<section><h3>Правка адреса {current.id}</h3><div className="admin-form"><label>Улица<input value={edit.street||''} onChange={e=>setEdit({...edit,street:e.target.value})}/></label><label>Дом<input value={edit.house||''} onChange={e=>setEdit({...edit,house:e.target.value})}/></label><label>Вид<select value={edit.kind} onChange={e=>setEdit({...edit,kind:e.target.value})}><option value="building">Здание</option><option value="street">Улица</option></select></label><label>Широта<input value={edit.lat} onChange={e=>setEdit({...edit,lat:e.target.value})}/></label><label>Долгота<input value={edit.lon} onChange={e=>setEdit({...edit,lon:e.target.value})}/></label><p className="admin-muted">Точка (point) редактируется только повторным импортом гео-данных.</p></div><div className="admin-inline-actions"><button className="admin-primary" onClick={save}>Сохранить</button><button className="danger" onClick={()=>{if(confirm('Удалить адрес «'+current.id+'»?'))call(()=>api('catalog_geo_addresses_delete',{address_id:current.id},{headers:authHeaders()})).then(()=>setSel(''));}}>Удалить</button></div></section>}</>;
}
function CatalogDrawer({onClose}){
 const [tab,setTab]=useState('services');
 return <Drawer title="Справочники" onClose={onClose}><Tabs value={tab} onChange={setTab} items={[["services","Службы"],["categories","Категории"],["entries","Записи классификатора"],["links","Связи записей"],["addresses","Гео-адреса"]]}/>{tab==='services'&&<ServicePanel/>}{tab==='categories'&&<CategoryPanel/>}{tab==='entries'&&<EntryPanel/>}{tab==='links'&&<LinkPanel/>}{tab==='addresses'&&<AddressPanel/>}</Drawer>;
}
function CatalogNotice({error}){return error?<p className="admin-note" role="alert">{error}</p>:null;}

function Dashboard({data,model,onOpen}){
 const warnings=(data.error?1:0)+(model.cards.some(c=>c.status!=='approved')?1:0), reviewed=data.sessions.filter(s=>s.status==='reviewed').length;
 return <main className="admin-main"><h1>Главная администратора</h1><p className="admin-subtitle">Сводка по объектам приложения</p><div className="admin-kpis">{[['users','Пользователи',model.users.length],['scenarios','Учебные сценарии',model.scenarios.length],['cards','Учебные карточки',model.cards.length],['trainings','Тренировки',model.trainings.length],['monitoring','Предупреждения',warnings]].map(([k,l,v])=><button key={k} onClick={()=>onOpen(k)}><span>{l}</span><strong>{v}</strong><i>›</i></button>)}</div><div className="admin-dashboard-grid"><section className="admin-panel admin-system"><header>Состояние системы</header><table><thead><tr><th>Компонент</th><th>Состояние</th><th>Последняя проверка</th><th>Метрика</th></tr></thead><tbody>{[['АРМ-112','Открыт','Интерфейс доступен'],['ИИ-модуль','Не проверен','Проверить в мониторинге'],['Учебные данные',data.error?'Ошибка':'Данные получены',`${data.sessions.length} работ`],['Карточки','Не проверено',`${model.cards.length} шт.`],['Сценарии','Данные получены',`${model.scenarios.length} шт.`]].map(([a,b,c])=><tr key={a}><td>{a}</td><td><Dot tone={b==='Нормально'?'green':b==='Не проверен'?'gray':'red'}/>{b}</td><td>{new Date().toLocaleString('ru-RU')}</td><td>{c}</td></tr>)}</tbody></table></section><section className="admin-panel admin-llm-summary"><header>ИИ-сервисы</header><div><b>Внешний ИИ</b><span><Dot tone="gray"/>Не проверен</span><small>Проверка выполняется в мониторинге</small></div><div><b>Маршрутизация запросов</b><span>Основная модель</span><small>Ключ задаётся локально</small></div><button onClick={()=>onOpen('monitoring')}>Открыть мониторинг</button></section><section className="admin-panel admin-events-panel"><header>Последние системные события</header>{[['Пользователи','Административная панель открыта'],['Тренировки',`Активных работ: ${data.sessions.filter(s=>s.status==='active').length}`],['Результаты',`Проверено работ: ${reviewed}`],['Карточки',`Утверждено: ${model.cards.filter(c=>c.status==='approved').length}`]].map(([a,b],i)=><p key={b}><span>{new Date(Date.now()-i*600000).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</span><b>{a}</b><em>{b}</em><Dot tone="blue"/></p>)}</section><section className="admin-panel admin-warning-panel"><header>Системные предупреждения</header>{warnings?<><article><Dot tone="orange"/><div><b>Есть элементы, требующие внимания</b><p>{model.cards.filter(c=>c.status!=='approved').length} карточек ещё не утверждено.</p></div></article>{data.error&&<article><Dot tone="red"/><div><b>Ошибка получения данных</b><p>{data.error}</p></div></article>}</>:<article><Dot/><div><b>Предупреждений нет</b><p>Критические компоненты отвечают штатно.</p></div></article>}</section></div></main>;
}

export default function Admin(){
 const [data,refresh]=useAdminData(),[open,setOpen]=useState(null);
 useEffect(()=>{if(!adminSignedIn())location.replace('/admin-login');},[]);
 const model=useMemo(()=>derived(data),[data.sessions,data.tasks,data.scenarios,data.trainings,data.users,data.groups]);
 const name=adminName();
 if(!adminSignedIn())return null;
 return <div className="admin-shell"><aside className="admin-sidebar"><div className="admin-brand"><strong>112</strong><span>ADMIN</span></div><nav>{menu.map(([k,ic,label])=><button key={k} className={(open===k||(!open&&k==='home'))?'active':''} onClick={()=>k==='home'?setOpen(null):setOpen(k)}><i>{ic}</i><span>{label}</span></button>)}</nav><footer><span>v 1.1.0</span><span>© 2026 EDU SIM</span></footer></aside><header className="admin-topbar"><button className="admin-bell" title="Уведомления">♧</button><div className="admin-profile"><span>♙</span><div><b>{name}</b><small>Администратор</small></div></div><button className="admin-exit" title="Выйти" onClick={()=>{adminLogout();location.assign('/');}}>↦</button></header><Dashboard data={data} model={model} onOpen={setOpen}/>{open==='users'&&<UsersDrawer model={model} onClose={()=>setOpen(null)}/>} {open==='catalog'&&<CatalogDrawer onClose={()=>setOpen(null)}/>} {open==='trainings'&&<TrainingsDrawer model={model} onClose={()=>setOpen(null)}/>} {open==='scenarios'&&<ScenariosDrawer model={model} onClose={()=>setOpen(null)}/>} {open==='cards'&&<CardsDrawer model={model} onClose={()=>setOpen(null)}/>} {open==='results'&&<ResultsDrawer data={data} onClose={()=>setOpen(null)}/>} {open==='monitoring'&&<MonitoringDrawer data={data} onClose={()=>setOpen(null)}/>} {open==='system'&&<SystemDrawer model={model} onClose={()=>setOpen(null)}/>} {open==='settings'&&<SettingsDrawer onClose={()=>setOpen(null)}/>}</div>;
}
